(V31_PKG / 'verification.py').write_text('"""V31: short-lived observation-only verification, no game names or solutions.\n\nAuto contracts extrapolate two identical rigid translations of a sparse colour\nfootprint. They are local hypotheses, NOT collision/safety certificates.\n"""\nimport json\nimport time\n\n\nclass ReplanRequired(BaseException):\n    """Stops the current Python snippet, including `except Exception` loops."""\n\n\ndef footprints(frame):\n    result = {}\n    for y, row in enumerate(getattr(frame, \'_grid\', ())):\n        for x, color in enumerate(row):\n            result.setdefault(int(color), set()).add((x, y))\n    return result\n\n\ndef snapshot(frame):\n    out = {\'level\': getattr(frame, \'level\', None),\n           \'shape\': list(getattr(frame, \'shape\', ()))}\n    for c, points in footprints(frame).items():\n        xs, ys = zip(*points)\n        out[\'c\' + str(c)] = [min(xs), min(ys), max(xs)+1, max(ys)+1, len(points)]\n    return out\n\n\ndef translations(before, after):\n    out = {}\n    for c, points in before.items():\n        other = after.get(c, set())\n        if not 2 <= len(points) <= 64 or len(points) != len(other):\n            continue\n        # One connected footprint only; multiple same-colour objects abstain.\n        reached = {next(iter(points))}\n        stack = list(reached)\n        while stack:\n            x, y = stack.pop()\n            for p in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):\n                if p in points and p not in reached:\n                    reached.add(p); stack.append(p)\n        if len(reached) != len(points):\n            continue\n        dx = min(x for x,y in other) - min(x for x,y in points)\n        dy = min(y for x,y in other) - min(y for x,y in points)\n        if 0 < abs(dx)+abs(dy) <= 8 and {(x+dx,y+dy) for x,y in points} == other:\n            out[c] = (dx, dy)\n    return out\n\n\nclass Verifier:\n    def __init__(self, execute, get_frame, normalize, emit=print,\n                 clock=time.monotonic, max_steps=64, timeout=25):\n        self.execute, self.get_frame, self.normalize = execute, get_frame, normalize\n        self.emit, self.clock = emit, clock\n        self.deadline, self.max_steps = clock()+timeout, max_steps\n        self.steps = 0\n        self.previous = None\n        self.journal = []\n        self.latched = None\n\n    def record(self, row, result=None):\n        self.journal.append(row)\n        if isinstance(result, dict):\n            result[\'v31_verification\'] = row\n        self.emit(\'V31_VERIFY \' + json.dumps(row, sort_keys=True, separators=(\',\', \':\')))\n\n    def halt(self, status, **fields):\n        self.latched = status\n        self.record(dict(status=status, step=self.steps, **fields))\n        raise ReplanRequired(\'V31 \'+status+\': inspect current_frame and replan in a new Python call\')\n\n    def action(self, actions, expect=None, observe=None):\n        items = self.normalize(actions)\n        if self.latched:\n            self.halt(self.latched)\n        if expect is not None:\n            if len(expect) != len(items) or any(not isinstance(e, dict) or not e for e in expect):\n                raise ValueError(\'expect requires one nonempty feature dict per action\')\n        elif observe is not None:\n            raise ValueError(\'observe requires expect\')\n        result = {}\n        executed_count = 0\n        executed_actions = []\n        for index, item in enumerate(items):\n            if self.steps >= self.max_steps:\n                self.halt(\'step_limit\')\n            if self.clock() >= self.deadline:\n                self.halt(\'timeout\')\n            frame = self.get_frame()\n            before = footprints(frame)\n            level = getattr(frame, \'level\', None)\n            shape = tuple(getattr(frame, \'shape\', ()))\n            signature = json.dumps(item, sort_keys=True)\n            expected = expect[index] if expect is not None else None\n            predicted_points = {}\n            source = \'explicit\' if expected is not None else \'none\'\n            if expected is None and self.previous is not None:\n                prev_sig, prev_level, prev_shape, last_points, delta, support = self.previous\n                if (signature, level, shape, before) == (prev_sig, prev_level, prev_shape, last_points):\n                    for c, d in delta.items():\n                        if support.get(c, 0) >= 2:\n                            predicted_points[c] = {(x+d[0],y+d[1]) for x,y in before[c]}\n                    if predicted_points:\n                        source = \'auto_translation\'\n            # Expectations are fixed BEFORE executing, never fitted to the outcome.\n            try:\n                result = self.execute([item]) or {}\n            except BaseException as exc:\n                self.latched = \'execute_error\'\n                self.record({\'status\':\'execute_error\',\'error_type\':type(exc).__name__,\n                             \'step\':self.steps,\'source\':source})\n                raise\n            self.steps += 1\n            executed_count += int(result.get(\'executed_count\', bool(result.get(\'executed\', True))))\n            executed_actions.extend(result.get(\'executed_actions\', []))\n            row = {\'step\':self.steps, \'action\':item, \'source\':source,\n                   \'contract_invoked\': source != \'none\'}\n            if not result.get(\'executed\', True):\n                row[\'status\'] = \'refused\'; self.record(row, result)\n                self.latched = \'refused\'\n                raise ReplanRequired(\'V31 refused: replan\')\n            terminal = next((k for k in (\'game_over\',\'level_completed\',\'done\',\'run_complete\') if result.get(k)), None)\n            current = self.get_frame()  # fetch AFTER host rebinds runtime_globals\n            if terminal or getattr(current,\'level\',None) != level:\n                row[\'status\'] = terminal or \'level_changed\'\n                self.record(row, result); self.previous = None\n                self.latched = row[\'status\']\n                # Stop even model-written loops around single action() calls.\n                raise ReplanRequired(\'V31 \'+row[\'status\']+\': next Python call starts with new state\')\n            after = footprints(current)\n            mismatch = {}\n            if expected is not None:\n                try:\n                    actual = observe(current) if observe is not None else snapshot(current)\n                    if not isinstance(actual, dict):\n                        raise TypeError(\'observer must return dict\')\n                    mismatch = {k:{\'expected\':v,\'actual\':actual.get(k),\'missing\':k not in actual}\n                                for k,v in expected.items() if k not in actual or actual[k] != v}\n                    row.update(expected=expected, actual={k:actual.get(k) for k in expected})\n                except BaseException as exc:\n                    self.latched = \'observer_error\'\n                    row.update(status=\'observer_error\',error_type=type(exc).__name__)\n                    self.record(row,result); raise\n            elif predicted_points:\n                # Compact summaries for humans; comparison uses ALL footprint pixels.\n                row[\'colors\'] = sorted(predicted_points)\n                def box(points):\n                    if not points: return None\n                    xs,ys=zip(*points)\n                    return [min(xs),min(ys),max(xs)+1,max(ys)+1,len(points)]\n                row[\'expected\'] = {str(c):box(p) for c,p in predicted_points.items()}\n                row[\'actual\'] = {str(c):box(after.get(c,set())) for c in predicted_points}\n                for c, points in predicted_points.items():\n                    if after.get(c, set()) != points:\n                        mismatch[str(c)] = {\'predicted_pixels\': sorted(points),\n                                            \'actual_pixels\': sorted(after.get(c, set()))[:65]}\n            row[\'status\'] = \'mismatch\' if mismatch else (\'verified\' if source != \'none\' else \'unverified\')\n            if mismatch:\n                row[\'mismatch\'] = mismatch\n            self.record(row, result)\n            if mismatch:\n                self.latched = \'mismatch\'; self.previous = None\n                raise ReplanRequired(\'V31 prediction mismatch: old plan suffix discarded; inspect current_frame\')\n            delta = translations(before, after)\n            support = {c:1 for c in delta}\n            if self.previous is not None:\n                p_sig,p_level,p_shape,p_points,p_delta,p_support = self.previous\n                if (signature,level,shape,before) == (p_sig,p_level,p_shape,p_points):\n                    for c,d in delta.items():\n                        if p_delta.get(c) == d:\n                            support[c] = p_support.get(c,0)+1\n            self.previous = (signature,level,shape,after,delta,support)\n            # Respect Duck\'s original noop stop within a batch.\n            if result.get(\'gameplay_changed\') is False:\n                break\n            if self.clock() >= self.deadline:\n                self.halt(\'timeout\')\n        return dict(result, executed_count=executed_count, executed_actions=executed_actions)\n\n    def checked_plan(self, actions, expectations, observe=None):\n        """Legacy zero-arg observer; action(..., observe=...) takes a fresh frame."""\n        observer = None if observe is None else lambda frame: observe()\n        self.record({\'status\':\'checked_plan_invoked\',\'step\':self.steps})\n        start = len(self.journal)\n        self.action(actions, expect=expectations, observe=observer)\n        return {\'status\':\'verified\', \'journal\':self.journal[start:]}\n', encoding='utf-8')
(V31_PKG / 'install_v31.py').write_text('"""Apply to original Duck harness AFTER cell 4/6 patch, INSTEAD OF V30 helper."""\nimport argparse\nimport ast\nimport difflib\nfrom pathlib import Path\nimport textwrap\n\nMARKER = \'# ASTRA_VERIFICATION_V31\'\nGUIDANCE = \'\'\'V31 action verification:\n- Ordinary action([...]) now checks a local rigid-motion prediction when two preceding identical actions support it. No prediction means unverified, not success. This is not a safety oracle.\n- Prefer action([a], expect=[{\'c3\': [x0,y0,x1,y1,pixel_count]}]) for a falsifiable prediction. snapshot() gives level, shape and c0..c15 colour bounding boxes with EXCLUSIVE x1/y1. A colour can contain several objects: use a custom feature observer when ambiguous.\n- For custom features: action(plan, expect=predicted_feature_dicts, observe=lambda frame: features(frame)). The observer receives the NEW frame after each action. Build all predictions BEFORE acting; do not copy measured outcomes into expectations. Never capture current_frame in a default argument.\n- On V31 mismatch/terminal/step limit the Python snippet ends: re-read the board and replan in the next call. No hidden suffix is retried. Maximum 64 actions per Python call.\n- Maintain a small evidence table: condition (shape/size/orientation/level), competing predictions, action, observed result. A successful level is not proof of every rule. New patterns or levels require a discriminating probe before transferring a rule.\n- When segmentation is ambiguous, infer object membership from a small controlled movement and frame_diff, not proximity alone. Build all graph nodes before edges. Keep separate phase/order hypotheses for actor movement, capture, enemy response and goal detection; a death under one joint event cannot establish every ordering.\n- After two inconclusive repetitions, change the test so competing hypotheses predict different visible outcomes. Test legal controls and conditional affordances; do not keep expanding an untested explanation.\n\'\'\'\n\n\ndef block():\n    source = (Path(__file__).parent/\'verification.py\').read_text()\n    source += \'\'\'\n_v31_raw_action = action\n_v31 = Verifier(_v31_raw_action, lambda: runtime_globals[\'current_frame\'], _normalize_actions)\nruntime_globals[\'action\'] = _v31.action\nruntime_globals[\'checked_plan\'] = _v31.checked_plan\nruntime_globals[\'snapshot\'] = lambda: snapshot(runtime_globals[\'current_frame\'])\nruntime_globals[\'verification_journal\'] = _v31.journal\nruntime_globals[\'ReplanRequired\'] = ReplanRequired\n\'\'\'\n    return textwrap.indent(MARKER+\'\\n\'+source.replace(\'"""\', "\'\'\'"), \'        \')\n\n\ndef validate_bootstrap(source):\n    tree = ast.parse(source)\n    for node in ast.walk(tree):\n        if isinstance(node, ast.Assign) and any(isinstance(t,ast.Name) and t.id==\'_SANDBOX_BOOTSTRAP\' for t in node.targets):\n            candidates = [n.value for n in ast.walk(node.value) if isinstance(n,ast.Constant)\n                          and isinstance(n.value,str) and MARKER in n.value]\n            if len(candidates) != 1: raise ValueError(\'cannot identify real sandbox bootstrap\')\n            compile(textwrap.dedent(candidates[0]), \'<V31 Duck bootstrap>\', \'exec\')\n            return\n    raise ValueError(\'missing Duck _SANDBOX_BOOTSTRAP\')\n\n\ndef patch_text(sandbox, prompts):\n    if MARKER in sandbox or \'ASTRA_CHECKED_PLAN_V1\' in sandbox:\n        raise ValueError(\'use pristine Duck+harness, not an already patched V30/V31 source\')\n    anchor=\'        runtime_globals["action"] = action\\n\'\n    prompt_anchor=\'STEP_VERIFICATION_ADDENDUM = (\\n\'\n    error_anchor=\'            TerminalStateActionError,\\n            Exception,\\n\'\n    if sandbox.count(anchor)!=1 or prompts.count(prompt_anchor)!=1 or sandbox.count(error_anchor)!=1:\n        raise ValueError(\'Duck anchors changed; refusing partial install\')\n    patched = sandbox.replace(anchor, anchor+block())\n    patched = patched.replace(error_anchor,\'            TerminalStateActionError,\\n            ReplanRequired,\\n            Exception,\\n\')\n    new_prompt = prompts.replace(prompt_anchor,prompt_anchor+\'    \'+repr(GUIDANCE+\'\\n\')+\'\\n\')\n    validate_bootstrap(patched); ast.parse(new_prompt)\n    return patched,new_prompt\n\n\ndef main():\n    ap=argparse.ArgumentParser();ap.add_argument(\'--root\',required=True)\n    ap.add_argument(\'--apply\',action=\'store_true\');ap.add_argument(\'--diff\',required=True)\n    args=ap.parse_args();root=Path(args.root)\n    paths=[root/\'inference/agent/python_tool_sandbox.py\',root/\'inference/agent/prompts.py\']\n    old=[p.read_text() for p in paths];new=patch_text(*old)\n    diff=\'\'.join(\'\'.join(difflib.unified_diff(a.splitlines(True),b.splitlines(True),\n        fromfile=\'a/\'+str(p.relative_to(root)),tofile=\'b/\'+str(p.relative_to(root)))) for p,a,b in zip(paths,old,new))\n    Path(args.diff).write_text(diff)\n    if args.apply:\n        for p,s in zip(paths,new):p.write_text(s)\n    print(\'V31 installed; outer modules + actual embedded bootstrap compiled\')\n\nif __name__==\'__main__\':main()\n', encoding='utf-8')
(V31_PKG / 'readiness_gate.py').write_text('"""Independent infrastructure preflight. Start game timers AFTER this returns."""\nimport json, time, urllib.request\n\n\ndef request_json(url, payload=None, timeout=10):\n    req=urllib.request.Request(url, data=None if payload is None else json.dumps(payload).encode(),\n                               headers={\'Content-Type\':\'application/json\'})\n    with urllib.request.urlopen(req,timeout=timeout) as response:\n        body=response.read()\n        return json.loads(body) if body else {}\n\n\ndef wait_for_model(base_url, model, timeout=2400, interval=2, request=request_json,\n                   clock=time.monotonic, sleep=time.sleep):\n    """A health response alone is insufficient; require a completion response.\n\n    Timeout is measured from THIS call, not notebook start. Failure raises and\n    must prevent benchmark launch. Startup time is not deducted from a game.\n    """\n    deadline=clock()+timeout;last=\'no response\'\n    while clock()<deadline:\n        try:\n            remaining=deadline-clock()\n            request(base_url.rstrip(\'/\')+\'/health\',timeout=min(10,remaining))\n            remaining=deadline-clock()\n            if remaining<=0:break\n            result=request(base_url.rstrip(\'/\')+\'/v1/chat/completions\',\n                           payload={\'model\':model,\'messages\':[{\'role\':\'user\',\'content\':\'Reply OK.\'}],\n                                    \'max_tokens\':4,\'temperature\':0},timeout=min(30,remaining))\n            if not isinstance(result,dict) or not result.get(\'choices\'):\n                raise RuntimeError(\'completion returned no choices\')\n            if clock()>deadline:break\n            return {\'ready\':True,\'model\':model}\n        except Exception as exc:\n            last=type(exc).__name__+\': \'+str(exc)\n        sleep(min(interval,max(0,deadline-clock())))\n    raise TimeoutError(\'Model unavailable; benchmark MUST NOT start. Last error: \'+last)\n', encoding='utf-8')
(V31_PKG / 'budget.py').write_text('"""Local-only deadlines. Official benchmark path does not call these helpers."""\nimport time\nfrom readiness_gate import request_json\n\n\ndef gameplay_deadline(started, ready, hard_budget, play_budget=1500, reserve=600):\n    if hard_budget <= 0 or play_budget <= 0 or reserve < 0 or ready < started:\n        raise ValueError(\'invalid budget/clock\')\n    hard_end = started + hard_budget - min(reserve, hard_budget/2)\n    if ready >= hard_end:\n        raise TimeoutError(\'not enough notebook budget after model startup\')\n    return min(ready+play_budget, hard_end)\n\n\ndef preflight(base_url, model, timeout=2100, interval=3, process=None,\n              request=request_json, clock=time.monotonic, sleep=time.sleep):\n    if timeout <= 0 or interval <= 0: raise ValueError(\'positive bounded wait required\')\n    deadline=clock()+timeout; last=\'not ready\'\n    while clock()<deadline:\n        if process is not None and process.poll() is not None:\n            raise RuntimeError(\'serving process exited; benchmark cancelled\')\n        try:\n            request(base_url+\'/health\',timeout=min(10,deadline-clock()))\n            left=deadline-clock()\n            if left<=0: break\n            result=request(base_url+\'/v1/chat/completions\',payload={\n                \'model\':model,\'messages\':[{\'role\':\'user\',\'content\':\'Reply OK.\'}],\n                \'max_tokens\':4,\'temperature\':0},timeout=min(30,left))\n            if result.get(\'choices\') and clock()<deadline:\n                if process is not None and process.poll() is not None:\n                    raise RuntimeError(\'serving process exited during readiness\')\n                return {\'ready\':True}\n            last=\'completion missing choices or deadline expired\'\n        except Exception as exc:\n            last=repr(exc)\n        sleep(min(interval,max(0,deadline-clock())))\n    raise TimeoutError(\'readiness failed; benchmark cancelled: \'+last)\n', encoding='utf-8')
(V31_PKG / 'test_v31.py').write_text('import ast\nimport json\nfrom pathlib import Path\nimport textwrap\nfrom types import SimpleNamespace\nimport unittest\nfrom verification import Verifier, ReplanRequired, snapshot\nfrom install_v31 import block, patch_text, validate_bootstrap\nfrom budget import gameplay_deadline, preflight\n\n\ndef frame(x=0, level=1, color=3, split=False):\n    g=[[0]*30 for _ in range(10)]\n    for yy in range(3,5):\n        for xx in range(x,x+2):g[yy][xx]=color\n    if split:g[8][29]=color\n    return SimpleNamespace(_grid=g,shape=(10,30),level=level)\n\n\nclass Tests(unittest.TestCase):\n    def rig(self, positions=(1,2,3,4), **kwargs):\n        state={\'frame\':frame(), \'calls\':[]}; events=[]\n        def execute(actions):\n            state[\'calls\']+=actions\n            state[\'frame\']=frame(positions[len(state[\'calls\'])-1])\n            return {\'executed\':True,\'executed_count\':1,\'executed_actions\':actions,\'gameplay_changed\':True}\n        v=Verifier(execute,lambda:state[\'frame\'],list,emit=events.append,**kwargs)\n        return v,state,events\n\n    def test_auto_actual_invocation(self):\n        v,s,e=self.rig();v.action([\'R\']*4)\n        self.assertEqual([r[\'status\'] for r in v.journal],[\'unverified\']*2+[\'verified\']*2)\n        self.assertEqual(sum(r[\'contract_invoked\'] for r in v.journal),2)\n        self.assertIn(\'expected\',v.journal[-1]);self.assertEqual(len(s[\'calls\']),4)\n\n    def test_mismatch_discards_suffix(self):\n        v,s,e=self.rig((1,2,7,8))\n        with self.assertRaises(ReplanRequired):v.action([\'R\']*4)\n        self.assertEqual(len(s[\'calls\']),3);self.assertEqual(v.journal[-1][\'status\'],\'mismatch\')\n        with self.assertRaises(ReplanRequired):v.action([\'R\'])\n        self.assertEqual(len(s[\'calls\']),3)\n\n    def test_fresh_observer_same_snippet(self):\n        v,s,e=self.rig();seen=[]\n        def observe(f):seen.append(f);return snapshot(f)\n        v.action([\'R\']*2,expect=[{\'c3\':[1,3,3,5,4]},{\'c3\':[2,3,4,5,4]}],observe=observe)\n        self.assertIsNot(seen[0],seen[1]);self.assertIs(seen[-1],s[\'frame\'])\n        self.assertEqual([r[\'status\'] for r in v.journal],[\'verified\']*2)\n\n    def test_missing_field_fails(self):\n        v,s,e=self.rig()\n        with self.assertRaises(ReplanRequired):v.action([\'R\'],expect=[{\'absent\':None}])\n        self.assertEqual(v.journal[-1][\'status\'],\'mismatch\')\n\n    def test_invalid_contract_no_action(self):\n        v,s,e=self.rig()\n        for value in ([],[{}],[{\'a\':1},{\'a\':2}]):\n            with self.assertRaises(ValueError):v.action([\'R\'],expect=value)\n        self.assertEqual(s[\'calls\'],[])\n\n    def test_terminal_each_flag_no_verification(self):\n        for flag in (\'game_over\',\'level_completed\',\'done\',\'run_complete\'):\n            calls=[];v=Verifier(lambda a:(calls.append(a) or {\'executed\':True,flag:True}),lambda:frame(),list,emit=lambda _:None)\n            with self.assertRaises(ReplanRequired):v.action([\'R\']*3,expect=[{\'bad\':0}]*3)\n            self.assertEqual(len(calls),1);self.assertEqual(v.journal[0][\'status\'],flag)\n\n    def test_level_change_without_flag(self):\n        v,s,e=self.rig();v.execute=lambda a:s.update(frame=frame(level=2)) or {\'executed\':True}\n        with self.assertRaises(ReplanRequired):v.action([\'R\',\'R\'])\n        self.assertEqual(v.journal[-1][\'status\'],\'level_changed\')\n\n    def test_noop_stops_batch(self):\n        calls=[];v=Verifier(lambda a:(calls.append(a) or {\'executed\':True,\'gameplay_changed\':False}),lambda:frame(),list,emit=lambda _:None)\n        v.action([\'R\']*3);self.assertEqual(len(calls),1)\n\n    def test_refusal(self):\n        v,s,e=self.rig();v.execute=lambda a:{\'executed\':False}\n        with self.assertRaises(ReplanRequired):v.action([\'R\']*3)\n        self.assertEqual(v.journal[-1][\'status\'],\'refused\')\n\n    def test_exception_not_retried(self):\n        v,s,e=self.rig();calls=[]\n        def fail(a):calls.append(a);raise TimeoutError(\'host\')\n        v.execute=fail\n        with self.assertRaises(TimeoutError):v.action([\'R\']*3)\n        self.assertEqual(len(calls),1);self.assertEqual(v.journal[-1][\'status\'],\'execute_error\')\n\n    def test_time_budget(self):\n        now=[0];v,s,e=self.rig(clock=lambda:now[0],timeout=1);now[0]=1\n        with self.assertRaises(ReplanRequired):v.action([\'R\'])\n        self.assertEqual(s[\'calls\'],[])\n\n    def test_step_budget_and_unusual_action(self):\n        v,s,e=self.rig(max_steps=2)\n        with self.assertRaises(ReplanRequired):v.action([\'UNKNOWN\']*3)\n        self.assertEqual(len(s[\'calls\']),2)\n\n    def test_ambiguous_color_abstains(self):\n        v,s,e=self.rig();s[\'frame\']=frame(split=True)\n        def move(a):\n            s[\'calls\']+=a;s[\'frame\']=frame(len(s[\'calls\']),split=True)\n            return {\'executed\':True}\n        v.execute=move;v.action([\'R\']*4)\n        self.assertTrue(all(r[\'status\']==\'unverified\' for r in v.journal))\n\n    def test_color_permutation(self):\n        for color in (1,8,15):\n            s={\'f\':frame(color=color),\'x\':0}\n            def move(a):s[\'x\']+=1;s[\'f\']=frame(s[\'x\'],color=color);return {\'executed\':True}\n            v=Verifier(move,lambda:s[\'f\'],list,emit=lambda _:None);v.action([\'R\']*3)\n            self.assertEqual(v.journal[-1][\'status\'],\'verified\')\n\n    def test_different_actions_do_not_transfer(self):\n        v,s,e=self.rig();v.action([\'R\',\'R\',\'U\',\'U\'])\n        self.assertTrue(all(r[\'status\']==\'unverified\' for r in v.journal))\n\n    def test_legacy_helper_invocation_and_stale_capture(self):\n        v,s,e=self.rig()\n        report=v.checked_plan([\'R\'],[{\'c3\':[1,3,3,5,4]}],lambda:snapshot(s[\'frame\']))\n        self.assertEqual(v.journal[0][\'status\'],\'checked_plan_invoked\')\n        self.assertEqual(report[\'status\'],\'verified\')\n        captured=s[\'frame\']\n        with self.assertRaises(ReplanRequired):\n            v.checked_plan([\'R\'],[{\'c3\':[2,3,4,5,4]}],lambda:snapshot(captured))\n\n    def test_metrics_deduplicate_history(self):\n        import tempfile\n        from summarize_verification import summarize\n        with tempfile.TemporaryDirectory() as temp:\n            m={\'role\':\'tool\',\'tool_call_id\':\'same\',\'content\':json.dumps({\'stdout\':\'V31_VERIFY \'+json.dumps({\'status\':\'verified\',\'source\':\'explicit\',\'contract_invoked\':True})})}\n            Path(temp,\'test_requests.jsonl\').write_text((json.dumps({\'messages\':[m]})+\'\\n\')*5)\n            result=summarize(temp)[\'games\'][0]\n            self.assertEqual(result[\'events\'],1);self.assertEqual(result[\'contract_invocations\'],1)\n\n    def test_embedded_install_wires_actual_action(self):\n        # Execute exactly the generated installation block in a Duck-shaped scope.\n        body=\'def launch(runtime_globals, action, _normalize_actions):\\n\'+textwrap.indent(textwrap.dedent(block()),\'    \')+\'\\n    return runtime_globals\\n\'\n        ns={};exec(body,ns)\n        v,s,e=self.rig();g={\'current_frame\':frame()}\n        def raw(a):r=v.execute(a);g[\'current_frame\']=s[\'frame\'];return r\n        ns[\'launch\'](g,raw,list)\n        g[\'action\']([\'R\']*2,expect=[{\'c3\':[1,3,3,5,4]},{\'c3\':[2,3,4,5,4]}])\n        self.assertEqual([r[\'status\'] for r in g[\'verification_journal\']],[\'verified\']*2)\n\n    def test_patch_outer_and_embedded_ast(self):\n        sandbox=\'import textwrap\\n_SANDBOX_BOOTSTRAP = textwrap.dedent(r"""\\n    def execute():\\n        runtime_globals["action"] = action\\n        try: pass\\n        except (\\n            TerminalStateActionError,\\n            Exception,\\n        ): pass\\n""")\\n\'\n        prompts=\'STEP_VERIFICATION_ADDENDUM = (\\n    "old"\\n)\\n\'\n        a,b=patch_text(sandbox,prompts);validate_bootstrap(a);ast.parse(b)\n        with self.assertRaises(ValueError):patch_text(a,b)\n        with self.assertRaises(ValueError):patch_text(sandbox.replace(\'action"]\',\'wrong"]\'),prompts)\n\n    def test_fake_clock_18min_startup_preserves_game_budget(self):\n        self.assertEqual(gameplay_deadline(100,1180,32400),2680)\n        self.assertEqual(gameplay_deadline(100,31800,32400),31900)\n        with self.assertRaises(TimeoutError):gameplay_deadline(100,31900,32400)\n\n    def test_preflight_requires_completion_and_is_bounded(self):\n        now=[0];calls=[]\n        def request(url,**kwargs):\n            calls.append(url)\n            if url.endswith(\'/health\'):return {}\n            if now[0]<18:return {}\n            return {\'choices\':[{}]}\n        result=preflight(\'http://local\',\'m\',timeout=30,interval=3,request=request,clock=lambda:now[0],sleep=lambda t:now.__setitem__(0,now[0]+t))\n        self.assertTrue(result[\'ready\']);self.assertEqual(now[0],18)\n        now[0]=0\n        with self.assertRaises(TimeoutError):preflight(\'http://local\',\'m\',timeout=9,interval=3,request=request,clock=lambda:now[0],sleep=lambda t:now.__setitem__(0,now[0]+t))\n        self.assertEqual(now[0],9)\n\n    def test_dead_process_fails_closed(self):\n        with self.assertRaises(RuntimeError):preflight(\'http://local\',\'m\',process=SimpleNamespace(poll=lambda:1))\n\nif __name__==\'__main__\':unittest.main(verbosity=2)\n', encoding='utf-8')
(V31_PKG / 'duck_smoke.py').write_text('"""CPU preflight against the REAL bundled Duck subprocess, before SGLang starts."""\nimport json\nfrom inference.agent.python_tool_sandbox import run_sandboxed_python\n\n\ndef state(x):\n    grid=[[5]*20 for _ in range(10)]\n    for y in (3,4):\n        for xx in (x,x+1):grid[y][xx]=3\n    frame={\'grid\':grid,\'shape\':[10,20],\'level\':1,\'step\':x,\'ascii\':\'\\n\'.join(\'\'.join(\'G\' if c==3 else \'B\' for c in row) for row in grid)}\n    return {\'current_frame\':frame,\'history\':[],\'valid_actions\':[\'RIGHT\'], \'last_action_call_result\':{}}\n\n\ndef check(code, positions, expected_calls, expected_status, terminal=False):\n    calls=[]\n    def handler(actions, **kwargs):\n        assert len(actions)==1, \'V31 must execute one action per host exchange\'\n        calls.append(actions)\n        x=positions[len(calls)-1]\n        result={\'executed\':True,\'executed_count\':1,\'executed_actions\':[\'RIGHT\'],\'gameplay_changed\':True}\n        if terminal:result[\'level_completed\']=True\n        return {\'action_result\':result,\'state\':state(x)}\n    result=run_sandboxed_python(code=code,timeout_seconds=10,initial_state=state(0),action_handler=handler)\n    assert len(calls)==expected_calls, (len(calls),expected_calls,result)\n    rows=[json.loads(s[len(\'V31_VERIFY \'):]) for s in result.get(\'stdout\',\'\').splitlines() if s.startswith(\'V31_VERIFY \')]\n    assert rows and rows[-1][\'status\']==expected_status, result\n    assert \'exited unexpectedly\' not in result.get(\'error\',\'\'), result\n    if expected_status==\'verified\':assert not result.get(\'error\'), result\n    return {\'calls\':len(calls),\'status\':rows[-1][\'status\']}\n\n\ndef main():\n    result={\n        \'automatic\':check("action([\'RIGHT\']*4)",[1,2,3,4],4,\'verified\'),\n        \'fresh\':check("action([\'RIGHT\']*2, expect=[{\'c3\':[1,3,3,5,4]},{\'c3\':[2,3,4,5,4]}])",[1,2],2,\'verified\'),\n        \'mismatch\':check("action([\'RIGHT\']*4)",[1,2,7,8],3,\'mismatch\'),\n        \'terminal\':check("action([\'RIGHT\']*4)",[1],1,\'level_completed\',True),\n    }\n    print(\'V31 REAL DUCK CPU PREFLIGHT PASSED\',json.dumps(result))\n\nif __name__==\'__main__\':main()\n', encoding='utf-8')
(V31_PKG / 'summarize_verification.py').write_text('"""Deduplicate tool replies across request histories; count actual V31 events."""\nimport argparse\nfrom collections import Counter\nimport json\nfrom pathlib import Path\n\n\ndef summarize(root):\n    totals=[]\n    for path in sorted(Path(root).rglob(\'*requests.jsonl\')):\n        replies={}\n        for line in path.open():\n            try:record=json.loads(line)\n            except json.JSONDecodeError:continue\n            for m in record.get(\'messages\',[]):\n                if m.get(\'role\')==\'tool\' and m.get(\'tool_call_id\'):\n                    # Keep the longest representation if later context truncates it.\n                    key=m[\'tool_call_id\'];content=m.get(\'content\',\'\')\n                    if len(content)>len(replies.get(key,\'\')):replies[key]=content\n        stats=Counter();events=0\n        for content in replies.values():\n            try:payload=json.loads(content);stdout=payload.get(\'stdout\',\'\')\n            except (ValueError,AttributeError):stdout=content\n            for line in stdout.splitlines():\n                if not line.startswith(\'V31_VERIFY \'):continue\n                try:row=json.loads(line[len(\'V31_VERIFY \'):])\n                except json.JSONDecodeError:stats[\'truncated_events\']+=1;continue\n                events+=1;stats[row[\'status\']]+=1\n                if row.get(\'contract_invoked\'):stats[\'contract_invocations\']+=1\n                if row.get(\'source\')==\'explicit\':stats[\'explicit_events\']+=1\n                if row.get(\'source\')==\'auto_translation\':stats[\'automatic_events\']+=1\n        checked=stats[\'verified\']+stats[\'mismatch\']\n        totals.append(dict(game=path.name.split(\'-\')[0],tool_replies=len(replies),events=events,\n            **stats,mismatch_fraction=(stats[\'mismatch\']/checked if checked else None)))\n    return {\'games\':totals,\'note\':\'Counts from captured stdout; truncation or missing final tool reply can undercount. No events is not successful verification.\'}\n\nif __name__==\'__main__\':\n    ap=argparse.ArgumentParser();ap.add_argument(\'root\');ap.add_argument(\'--out\',required=True)\n    a=ap.parse_args();result=summarize(a.root);Path(a.out).write_text(json.dumps(result,indent=2));print(json.dumps(result,indent=2))\n', encoding='utf-8')
